\set ON_ERROR_STOP on
begin;

-- ══════ РОСГОССТРАХ №152: типовая программа + общие условия (тип B, формы Ф1/Ф2) ══════
delete from coverage_rule where document_id = (select id from program_document where storage_path='programs/rgs_dms_152.pdf');
with d as (select id, insurance_company_id from program_document where storage_path='programs/rgs_dms_152.pdf')
insert into coverage_rule (document_id, insurance_company_id, program_name, service_class, service_pattern, verdict, condition_text, limit_amount, clause, scope_level, overridable)
select d.id, d.insurance_company_id, v.pn, v.sc, v.sp, v.vd, v.ct, v.la, v.cl,
       case when v.pn is null then 'insurer' else 'program' end, false
from d cross join (values
('Стоматологическая помощь (типовая программа РГС)','стоматология-приёмы','приём стоматолог терапевт хирург консультативный','covered',null,null,'п. 4.1'),
('Стоматологическая помощь (типовая программа РГС)','стоматология-терапия','анестезия местная аппликационная инфильтрационная проводниковая интралигаментарная','covered',null,null,'п. 4.2'),
('Стоматологическая помощь (типовая программа РГС)','диагностика','радиовизиография рентгеновские снимки ортопантомограмма электроодонтодиагностика','covered',null,null,'п. 4.3'),
('Стоматологическая помощь (типовая программа РГС)','стоматология-терапия','лечение кариеса поверхностного среднего глубокого прокладки пломбировочные материалы','conditional','восстановление коронковой части — при разрушении не более чем на 50%',null,'п. 4.4.1'),
('Стоматологическая помощь (типовая программа РГС)','стоматология-терапия','лечение пульпита периодонтита распломбировка пломбирование каналов гуттаперча термофил','covered',null,null,'п. 4.4.2'),
('Стоматологическая помощь (типовая программа РГС)','стоматология-терапия','разрушение коронковой части более 50%','conditional','покрывается только эндодонтическое лечение, включая пломбирование каналов; восстановление коронки не входит',null,'п. 4.4.2'),
('Стоматологическая помощь (типовая программа РГС)','пародонтология','лечение пародонтита гингивита стоматита зубные отложения закрытый кюретаж','conditional','пародонтит только I и II степени; удаление над- и поддесневых отложений, обработка карманов',null,'п. 4.4.3'),
('Стоматологическая помощь (типовая программа РГС)','стоматология-терапия','лечение слизистой полости рта языка повязки','covered',null,null,'п. 4.4.4'),
('Стоматологическая помощь (типовая программа РГС)','стоматология-профилактика','лечение гиперестезии эмали покрытие фторсодержащими препаратами','covered',null,null,'п. 4.4.5'),
('Стоматологическая помощь (типовая программа РГС)','стоматология-терапия','терапевтическое лечение заболеваний слюнных желёз','covered',null,null,'п. 4.4.6'),
('Стоматологическая помощь (типовая программа РГС)','стоматология-хирургия','удаление зуб простое сложное отслаивание лоскута','covered',null,null,'п. 4.5.1'),
('Стоматологическая помощь (типовая программа РГС)','стоматология-хирургия','удаление ретинированных дистопированных зубов','covered','с отслаиванием слизисто-надкостничного лоскута',null,'п. 4.5.1'),
('Стоматологическая помощь (типовая программа РГС)','стоматология-хирургия','иссечение капюшона перикоронарит разрезы периостит вскрытие абсцессов','covered','включая остановку кровотечения и наложение швов',null,'п. 4.5.1'),
('Стоматологическая помощь (типовая программа РГС)','стоматология-хирургия','удаление доброкачественных образований полости рта','covered',null,null,'п. 4.5.2'),
('Стоматологическая помощь (типовая программа РГС)','стоматология-хирургия','зубосохраняющие операции резекция верхушки корня цистэктомия','covered',null,null,'п. 4.5.3'),
('Стоматологическая помощь (типовая программа РГС)','стоматология-физио','физиотерапевтическое лечение','covered',null,null,'п. 4.6'),
('Стоматологическая помощь (типовая программа РГС)','стоматология-приёмы','динамическое наблюдение стоматологом детей до 8 лет','conditional','дополнительно для детей от 0 до 8 лет',null,'п. 4.7'),
(null,'общие-условия','страховой случай обращение в медорганизацию по программе','conditional','обращение в течение срока договора в организацию из числа предусмотренных договором за услугами по программе',null,'Раздел 3 «СТРАХОВОЙ РИСК И СТРАХОВЫЕ СЛУЧАИ»'),
(null,'общие-условия','период ожидания','excluded','обращение в период ожидания страховым случаем не является',null,'Сноска 55 «Период ожидания»'),
(null,'общие-условия','услуги не предусмотренные программой','excluded',null,null,'Сноска 55 «не предусмотренных, Программой, не является страховым случаем»'),
(null,'общие-условия','франшиза','conditional','договором может быть предусмотрена франшиза',null,'Раздел 5 «ФРАНШИЗА»'),
(null,'общие-условия','страховая сумма лимит','conditional','обязательства страховщика ограничены страховой суммой договора',null,'Раздел 4 «ПОРЯДОК ОПРЕДЕЛЕНИЯ СТРАХОВОЙ СУММЫ»'),
(null,'лекарства','лекарственные средства вне перечня','excluded','перечень неоплачиваемых лекарственных средств установлен Правилами',null,'Раздел «Страховщик не оплачивает следующие лекарственные средства»'),
(null,'имплантация','имплантация при реконструктивном лечении','conditional','по стационарной программе — в пределах суммы, указанной в договоре, включая стоимость имплантатов',null,'п. 21.2.2.3')
) as v(pn, sc, sp, vd, ct, la, cl);

-- ══════ РЕНЕССАНС: правила ДМС ред. 7.0 (тип B) ══════
delete from coverage_rule where document_id = (select id from program_document where storage_path='programs/renins_dms.pdf');
with d as (select id, insurance_company_id from program_document where storage_path='programs/renins_dms.pdf')
insert into coverage_rule (document_id, insurance_company_id, program_name, service_class, service_pattern, verdict, condition_text, limit_amount, clause, scope_level, overridable)
select d.id, d.insurance_company_id, null, v.sc, v.sp, v.vd, v.ct, null, v.cl, 'insurer', false
from d cross join (values
('общие-условия','страховой случай обращение в медорганизацию по программе','conditional','обращение в срок договора в организацию из числа предусмотренных договором или согласованных со Страховщиком, за услугами по Программе','п. 4.2.1'),
('общие-условия','телемедицина дистанционное обращение','conditional','возможно, если прямо предусмотрено договором страхования','п. 4.2.1'),
('лекарства','приобретение медикаментов в аптечной организации','conditional','только по назначению лечащего врача и в аптеке из числа предусмотренных договором','п. 4.2.2'),
('общие-условия','репатриация останков','covered','при смерти застрахованного в период страхования — до ближайшего к месту жительства аэропорта/вокзала','п. 4.2.3'),
('общие-исключения','алкогольное наркотическое токсическое опьянение психоактивные вещества','excluded','включая приём лекарств без назначения врача','п. 4.3.1'),
('общие-исключения','умышленное преступление','excluded','если находится в прямой причинной связи со страховым случаем','п. 4.3.1'),
('общие-исключения','умышленное причинение себе вреда покушение на самоубийство','excluded','кроме доведения третьими лицами и кроме случаев, когда договор действовал не менее 2 лет','п. 4.3.1'),
('общие-исключения','ядерный взрыв радиация военные действия забастовки стихийные бедствия терроризм','excluded',null,'п. 4.3.1'),
('общие-условия','услуги не предусмотренные договором и программой','excluded',null,'п. 4.3.2'),
('общие-условия','услуги в медорганизации не предусмотренной договором','excluded','если обращение не согласовано со Страховщиком','п. 4.3.2'),
('общие-условия','услуги не назначенные лечащим врачом медицински необоснованные','excluded',null,'п. 4.3.2'),
('общие-условия','услуги после окончания срока договора','excluded','кроме экстренной стационарной помощи, начавшейся в срок договора, — не более 15 календарных дней после окончания','п. 4.3.2'),
('общие-условия','страховая сумма тариф франшиза','conditional','страховая сумма определяется соглашением сторон, может устанавливаться на каждое застрахованное лицо','п. 5.1 – 5.2'),
('общие-условия','порядок обращения за медицинской помощью','conditional','порядок обращения и определения выплаты установлен разделом 7 Правил','Раздел 7 «Порядок обращения за медицинской помощью»')
) as v(sc, sp, vd, ct, cl);

-- ══════ ЗЕТТА: правила ДМС (приказ №75 от 11.09.2023, тип B) ══════
delete from coverage_rule where document_id = (select id from program_document where storage_path='programs/zetta_dms.pdf');
with d as (select id, insurance_company_id from program_document where storage_path='programs/zetta_dms.pdf')
insert into coverage_rule (document_id, insurance_company_id, program_name, service_class, service_pattern, verdict, condition_text, limit_amount, clause, scope_level, overridable)
select d.id, d.insurance_company_id, null, v.sc, v.sp, v.vd, v.ct, null, v.cl, 'insurer', false
from d cross join (values
('общие-условия','услуги не предусмотренные программой вариантом договором','excluded',null,'п. 4.4.1.1'),
('общие-исключения','алкогольное наркотическое токсическое опьянение психоактивные вещества','excluded','включая остаточные явления опьянения, подтверждённые медицинскими документами','п. 4.4.1.2'),
('общие-исключения','противоправные действия квалифицированные правоохранительными органами','excluded',null,'п. 4.4.1.3'),
('общие-исключения','намеренное причинение вреда своему здоровью суицидальные попытки','excluded','кроме доведения противоправными действиями третьих лиц, подтверждёнными судебным решением','п. 4.4.1.4'),
('общие-условия','услуги не назначенные лечащим врачом по желанию застрахованного','excluded',null,'п. 4.4.1.5'),
('общие-условия','услуги вне порядков и стандартов оказания медицинской помощи без показаний','excluded','несоответствие Порядкам и Стандартам Минздрава','п. 4.4.1.6'),
('общие-исключения','заболевания представляющие опасность для окружающих карантинные','excluded','включая заболевания из перечня Правительства РФ и Минздрава, их осложнения и последствия','п. 4.4.1.7'),
('общие-условия','услуги в медорганизациях не предусмотренных договором','excluded','если обращение не согласовано и не организовано Страховщиком','п. 4.4.1.9'),
('общие-условия','события вне срока страхования до вступления договора в силу','excluded','в том числе до окончания периода ожидания','п. 4.4.1.10')
) as v(sc, sp, vd, ct, cl);

-- ══════ ЭНЕРГОГАРАНТ: правила ДМС №125 (тип B) ══════
delete from coverage_rule where document_id = (select id from program_document where storage_path='programs/energogarant_dms_125.pdf');
with d as (select id, insurance_company_id from program_document where storage_path='programs/energogarant_dms_125.pdf')
insert into coverage_rule (document_id, insurance_company_id, program_name, service_class, service_pattern, verdict, condition_text, limit_amount, clause, scope_level, overridable)
select d.id, d.insurance_company_id, null, v.sc, v.sp, v.vd, v.ct, null, v.cl, 'insurer', false
from d cross join (values
('общие-условия','страховой случай обращение за медицинской помощью по программе','conditional','страховым случаем признаётся обращение застрахованного за услугами, входящими в программу страхования','Раздел 4 «СТРАХОВЫЕ РИСКИ И СТРАХОВЫЕ СЛУЧАИ»'),
('общие-исключения','исключения из страхового покрытия','excluded','перечень исключений установлен разделом 5 Правил и программой к договору','Раздел 5 «ИСКЛЮЧЕНИЯ ИЗ СТРАХОВОГО ПОКРЫТИЯ»'),
('общие-условия','страховая сумма франшиза','conditional','страховая сумма и франшиза определяются договором страхования','Раздел 6 «СТРАХОВАЯ СУММА. ФРАНШИЗА»')
) as v(sc, sp, vd, ct, cl);

select left(ic.name,20) || ' | ' || left(pd.title,40) || ' | правил: ' ||
  (select count(*) from coverage_rule cr where cr.document_id = pd.id)
from program_document pd join insurance_company ic on ic.id = pd.insurance_company_id
where pd.superseded_by_id is null order by ic.name;
commit;
